import java.lang.reflect.Constructor;
import java.util.concurrent.atomic.AtomicInteger;

public class SingletonDemo {

    // 1. Enum singleton: the JVM guarantees one instance, even against reflection/serialization.
    enum AppConfig {
        INSTANCE;
        private final String env = System.getProperty("app.env", "dev");
        String env() { return env; }
    }

    // 2. Initialization-on-demand holder: lazy, thread-safe, no locks in our code.
    static final class IdGenerator {
        private static final AtomicInteger created = new AtomicInteger();
        private final AtomicInteger next = new AtomicInteger(1000);

        private IdGenerator() { created.incrementAndGet(); }

        private static class Holder {
            static final IdGenerator INSTANCE = new IdGenerator();
        }

        static IdGenerator getInstance() { return Holder.INSTANCE; }
        int nextId() { return next.getAndIncrement(); }
    }

    // 3. Eager singleton with a private constructor: reflection can still break it.
    static final class Registry {
        static final Registry INSTANCE = new Registry();
        private Registry() { }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("env = " + AppConfig.INSTANCE.env());
        boolean same = AppConfig.INSTANCE == AppConfig.valueOf("INSTANCE");
        System.out.println("same enum instance: " + same);

        System.out.println("instances before first use: " + IdGenerator.created.get());
        System.out.println("id " + IdGenerator.getInstance().nextId());
        System.out.println("id " + IdGenerator.getInstance().nextId());
        System.out.println("instances after: " + IdGenerator.created.get());

        Constructor<Registry> c = Registry.class.getDeclaredConstructor();
        c.setAccessible(true);
        Registry second = c.newInstance();
        System.out.println("registry broken by reflection: " + (second != Registry.INSTANCE));

        try {
            Constructor<?> ec = AppConfig.class.getDeclaredConstructors()[0];
            ec.setAccessible(true);
            ec.newInstance("X", 1);
        } catch (Exception e) {
            System.out.println("enum reflection: " + e.getClass().getSimpleName()
                + ": " + e.getMessage());
        }
    }
}

public final class LazyService {
    private static volatile LazyService instance;   // volatile is essential

    private LazyService() { }

    public static LazyService getInstance() {
        LazyService local = instance;               // one volatile read on the fast path
        if (local == null) {
            synchronized (LazyService.class) {
                local = instance;
                if (local == null) {
                    instance = local = new LazyService();
                }
            }
        }
        return local;
    }
}

import java.util.List;
import java.util.Map;
import java.util.function.Supplier;

public class FactoryDemo {

    sealed interface Shape permits Circle, Rect, Square { double area(); }
    record Circle(double r) implements Shape {
        public double area() { return Math.PI * r * r; }
    }
    record Rect(double w, double h) implements Shape {
        public double area() { return w * h; }
    }
    record Square(double side) implements Shape {
        public double area() { return side * side; }
    }

    // Static factory method with a descriptive name and validation.
    static Shape of(String kind, double... dims) {
        return switch (kind) {
            case "circle" -> new Circle(dims[0]);
            case "rect"   -> new Rect(dims[0], dims[1]);
            case "square" -> new Square(dims[0]);
            default -> throw new IllegalArgumentException("unknown shape: " + kind);
        };
    }
    // A registry of suppliers: new kinds can be added without editing a switch.
    interface Notifier { String send(String msg); }
    static final Map<String, Supplier<Notifier>> NOTIFIERS = Map.of(
        "email", () -> msg -> "EMAIL: " + msg,
        "sms",   () -> msg -> "SMS: " + msg
    );

    static Notifier notifier(String channel) {
        Supplier<Notifier> s = NOTIFIERS.get(channel);
        if (s == null) throw new IllegalArgumentException("no channel " + channel);
        return s.get();
    }

    public static void main(String[] args) {
        List<Shape> shapes = List.of(of("circle", 1.5), of("rect", 2, 3), of("square", 4));
        for (Shape s : shapes) {
            System.out.printf("%-28s area=%.2f%n", s, s.area());
        }
        System.out.println(notifier("sms").send("order shipped"));
        try {
            of("hexagon");
        } catch (IllegalArgumentException e) {
            System.out.println("caught: " + e.getMessage());
        }
        // JDK examples of static factories
        System.out.println(List.of(1, 2, 3) + " " + Integer.valueOf(127)
            + " " + java.time.LocalDate.of(2026, 10, 11));
    }
}

import java.util.ArrayList;
import java.util.List;

public class BuilderDemo {

    static final class Order {
        private final String customer;
        private final List<String> items;
        private final boolean express;
        private final String note;
        private Order(Builder b) {
            this.customer = b.customer;
            this.items = List.copyOf(b.items);
            this.express = b.express;
            this.note = b.note;
        }

        static Builder builder(String customer) { return new Builder(customer); }

        @Override public String toString() {
            return "Order[" + customer + ", items=" + items + ", express=" + express
                + ", note=" + note + "]";
        }

        static final class Builder {
            private final String customer;
            private final List<String> items = new ArrayList<>();
            private boolean express;
            private String note = "";

            private Builder(String customer) { this.customer = customer; }

            Builder item(String name) { items.add(name); return this; }
            Builder express(boolean v) { this.express = v; return this; }
            Builder note(String n) { this.note = n; return this; }

            Order build() {
                if (customer == null || customer.isBlank())
                    throw new IllegalStateException("customer required");
                if (items.isEmpty())
                    throw new IllegalStateException("at least one item required");
                if (express && items.size() > 3)
                    throw new IllegalStateException("express orders hold at most 3 items");
                return new Order(this);
            }
        }
    }

    // Records need no builder for small cases: use a compact constructor for validation.
    record Point(int x, int y) {
        Point {
            if (x < 0 || y < 0) throw new IllegalArgumentException("negative coordinate");
        }
    }

    public static void main(String[] args) {
        Order o = Order.builder("Asha").item("book").item("pen").express(true)
                       .note("gift wrap").build();
        System.out.println(o);

        try {
            Order.builder("Ravi").build();
        } catch (IllegalStateException e) {
            System.out.println("rejected: " + e.getMessage());
        }
        try {
            Order.builder("Ravi").item("a").item("b").item("c").item("d").express(true).build();
        } catch (IllegalStateException e) {
            System.out.println("rejected: " + e.getMessage());
        }
        System.out.println(new Point(1, 2));
        // StringBuilder and Stream.Builder are builders in the JDK
        System.out.println(new StringBuilder().append("a").append(1).append(true));
    }
}

import java.util.ArrayList;
import java.util.List;

public class PrototypeDemo {

    static class Template {
        String title;
        List<String> tags;

        Template(String title, List<String> tags) {
            this.title = title;
            this.tags = tags;
        }

        // Copy constructor: the recommended replacement for clone()
        Template(Template other) {
            this.title = other.title;
            this.tags = new ArrayList<>(other.tags);   // deep copy of the mutable part
        }

        Template shallowCopy() { return new Template(title, tags); } // shares the list!

        @Override public String toString() { return title + tags; }
    }

    static class LegacyDoc implements Cloneable {
        int[] data = {1, 2, 3};
        @Override public LegacyDoc clone() {
            try {
                return (LegacyDoc) super.clone();        // shallow: data array is shared
            } catch (CloneNotSupportedException e) {
                throw new AssertionError(e);
            }
        }
    }

    public static void main(String[] args) {
        Template base = new Template("Report", new ArrayList<>(List.of("draft")));

        Template shallow = base.shallowCopy();
        shallow.tags.add("shared-bug");
        System.out.println("after shallow edit, base = " + base);

        Template base2 = new Template("Report", new ArrayList<>(List.of("draft")));
        Template deep = new Template(base2);
        deep.title = "Report (copy)";
        deep.tags.add("v2");
        System.out.println("base2 = " + base2 + "  deep = " + deep);

        LegacyDoc a = new LegacyDoc();
        LegacyDoc b = a.clone();
        b.data[0] = 99;
        System.out.println("clone() shares the array: a.data[0] = " + a.data[0]);
    }
}

import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;

public class AdapterDecoratorDemo {

    // ---- Adapter: make an old API fit the interface our code expects ----
    interface Thermometer { double celsius(); }
    static class LegacyFahrenheitSensor {          // we cannot change this class
        double readFahrenheit() { return 98.6; }
    }

    static class SensorAdapter implements Thermometer {
        private final LegacyFahrenheitSensor sensor;
        SensorAdapter(LegacyFahrenheitSensor sensor) { this.sensor = sensor; }
        @Override public double celsius() { return (sensor.readFahrenheit() - 32) * 5 / 9; }
    }

    // ---- Decorator on our own interface: wrap, add behaviour, same type ----
    interface Text { String render(); }
    record Plain(String s) implements Text { public String render() { return s; } }
    record Bold(Text inner) implements Text {
        public String render() { return "<b>" + inner.render() + "</b>"; }
    }
    record Shout(Text inner) implements Text {
        public String render() { return inner.render().toUpperCase() + "!"; }
    }

    // ---- Decorator in the style of java.io: a FilterInputStream subclass ----
    static class UpperCaseInputStream extends FilterInputStream {
        UpperCaseInputStream(InputStream in) { super(in); }
        @Override public int read() throws IOException {
            int c = super.read();
            return c == -1 ? -1 : Character.toUpperCase(c);
        }
        @Override public int read(byte[] b, int off, int len) throws IOException {
            int n = super.read(b, off, len);
            for (int i = off; i < off + Math.max(n, 0); i++) {
                b[i] = (byte) Character.toUpperCase(b[i]);
            }
            return n;
        }
    }

    public static void main(String[] args) throws IOException {
        Thermometer t = new SensorAdapter(new LegacyFahrenheitSensor());
        System.out.printf("body temperature: %.1f C%n", t.celsius());

        Text msg = new Shout(new Bold(new Plain("sale")));
        System.out.println(msg.render());
        System.out.println(new Bold(new Shout(new Plain("sale"))).render());

        byte[] bytes = "hello\ndecorators\n".getBytes(StandardCharsets.UTF_8);
        InputStream raw = new ByteArrayInputStream(bytes);
        // InputStreamReader ADAPTS bytes to chars; BufferedReader DECORATES a Reader with buffering
        try (BufferedReader r = new BufferedReader(
                new InputStreamReader(new UpperCaseInputStream(raw), StandardCharsets.UTF_8))) {
            String line;
            while ((line = r.readLine()) != null) System.out.println(line);
        }
    }
}

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class FacadeProxyDemo {

    // ---- Facade: one simple entry point over several subsystems ----
    static class Inventory {
        boolean reserve(String sku) { System.out.println("  reserve " + sku); return true; }
    }
    static class Payment {
        boolean charge(double amt) { System.out.println("  charge " + amt); return true; }
    }
    static class Shipping {
        void ship(String sku) { System.out.println("  ship " + sku); }
    }

    static class OrderFacade {
        private final Inventory inventory = new Inventory();
        private final Payment payment = new Payment();
        private final Shipping shipping = new Shipping();

        boolean placeOrder(String sku, double price) {
            if (!inventory.reserve(sku)) return false;
            if (!payment.charge(price)) return false;
            shipping.ship(sku);
            return true;
        }
    }

    // ---- Proxy: same interface, controls access to the real object ----
    interface Repository {
        String find(int id);
        void save(String value);
    }

    static class RealRepository implements Repository {
        public String find(int id) { return "row-" + id; }
        public void save(String value) {
            if (value.isEmpty()) throw new IllegalArgumentException("empty");
        }
    }

    // Static proxy: a caching proxy written by hand
    static class CachingRepository implements Repository {
        private final Repository target;
        private final Map<Integer, String> cache = new HashMap<>();
        CachingRepository(Repository target) { this.target = target; }
        public String find(int id) {
            return cache.computeIfAbsent(id, k -> {
                System.out.println("  (cache miss " + k + ")");
                return target.find(k);
            });
        }
        public void save(String v) { cache.clear(); target.save(v); }
    }

    // Dynamic proxy: one handler can wrap ANY interface (the idea behind Spring AOP)
    @SuppressWarnings("unchecked")
    static <T> T logging(T target, Class<T> iface, List<String> log) {
        InvocationHandler h = (proxy, method, args) -> {
            try {
                Object result = method.invoke(target, args);
                log.add(method.getName() + " ok");
                return result;
            } catch (InvocationTargetException e) {
                log.add(method.getName() + " failed: " + e.getCause().getMessage());
                throw e.getCause();
            }
        };
        return (T) Proxy.newProxyInstance(iface.getClassLoader(), new Class<?>[] {iface}, h);
    }

    public static void main(String[] args) {
        System.out.println("facade:");
        System.out.println("  result " + new OrderFacade().placeOrder("BOOK-1", 12.5));

        Repository cached = new CachingRepository(new RealRepository());
        System.out.println("caching proxy:");
        System.out.println("  " + cached.find(7));
        System.out.println("  " + cached.find(7));

        List<String> log = new ArrayList<>();
        Repository repo = logging(new RealRepository(), Repository.class, log);
        repo.find(1);
        try {
            repo.save("");
        } catch (IllegalArgumentException e) {
            log.add("caller saw " + e.getMessage());
        }
        System.out.println("dynamic proxy log: " + log);
        System.out.println("proxy class is generated: " + Proxy.isProxyClass(repo.getClass()));
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.DoubleUnaryOperator;

public class StrategyObserverDemo {

    // ---- Strategy: the algorithm is a parameter. A functional interface + lambdas ----
    @FunctionalInterface
    interface DiscountPolicy { double apply(double total); }

    static double checkout(double total, DiscountPolicy policy) { return policy.apply(total); }

    // ---- Observer: subject keeps a list of listeners and notifies them ----
    static class PriceFeed {
        private final List<Consumer<Double>> listeners = new ArrayList<>();
        Runnable subscribe(Consumer<Double> l) {
            listeners.add(l);
            return () -> listeners.remove(l);          // unsubscribe handle
        }
        void publish(double price) {
            // iterate over a copy so a listener may unsubscribe while being notified
            for (Consumer<Double> l : List.copyOf(listeners)) l.accept(price);
        }
    }

    // ---- Template Method: fixed skeleton, subclasses fill the steps ----
    abstract static class ReportJob {
        final void run() {                  // final: subclasses cannot reorder the steps
            List<String> rows = load();
            System.out.println(header());
            rows.stream().map(this::format).forEach(System.out::println);
            System.out.println("rows: " + rows.size());
        }
        abstract List<String> load();
        abstract String format(String row);
        String header() { return "== report =="; }       // hook with a default
    }

    static class CsvReport extends ReportJob {
        List<String> load() { return List.of("1,Asha", "2,Ravi"); }
        String format(String row) { return row.replace(',', ';'); }
    }

    public static void main(String[] args) {
        DiscountPolicy none = t -> t;
        DiscountPolicy tenPercent = t -> t * 0.9;
        DiscountPolicy flat = t -> Math.max(0, t - 15);
        for (DiscountPolicy p : List.of(none, tenPercent, flat)) {
            System.out.println(checkout(100, p));
        }
        DoubleUnaryOperator composed = ((DoubleUnaryOperator) (t -> t * 0.9)).andThen(t -> t - 5);
        System.out.println("composed: " + composed.applyAsDouble(100));

        PriceFeed feed = new PriceFeed();
        List<String> audit = new ArrayList<>();
        Runnable stopPrinting = feed.subscribe(p -> System.out.println("display: " + p));
        feed.subscribe(p -> audit.add("seen " + p));
        feed.publish(101.5);
        stopPrinting.run();
        feed.publish(102.0);
        System.out.println(audit);

        new CsvReport().run();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

public class CommandStateDemo {

    // ---- Command: a request as an object, so it can be queued, logged, undone ----
    static class Editor { final StringBuilder text = new StringBuilder(); }

    interface Command { void execute(); void undo(); }

    record Append(Editor ed, String s) implements Command {
        public void execute() { ed.text.append(s); }
        public void undo() { ed.text.setLength(ed.text.length() - s.length()); }
    }

    static class History {
        private final Deque<Command> done = new ArrayDeque<>();
        void run(Command c) { c.execute(); done.push(c); }
        void undo() { if (!done.isEmpty()) done.pop().undo(); }
    }

    // ---- State: behaviour depends on the current state; each state decides the next ----
    enum OrderState {
        NEW {
            OrderState pay() { return PAID; }
            OrderState ship() { throw new IllegalStateException("pay first"); }
        },
        PAID {
            OrderState pay() { throw new IllegalStateException("already paid"); }
            OrderState ship() { return SHIPPED; }
        },
        SHIPPED {
            OrderState pay() { throw new IllegalStateException("already paid"); }
            OrderState ship() { throw new IllegalStateException("already shipped"); }
        };
        abstract OrderState pay();
        abstract OrderState ship();
    }

    public static void main(String[] args) {
        Editor ed = new Editor();
        History h = new History();
        h.run(new Append(ed, "Hello"));
        h.run(new Append(ed, ", world"));
        System.out.println(ed.text);
        h.undo();
        System.out.println(ed.text);
        h.undo();
        System.out.println("[" + ed.text + "]");

        OrderState s = OrderState.NEW;
        try {
            s.ship();
        } catch (IllegalStateException e) {
            System.out.println("NEW.ship(): " + e.getMessage());
        }
        s = s.pay();
        System.out.println(s);
        s = s.ship();
        System.out.println(s);
        try {
            s.pay();
        } catch (IllegalStateException e) {
            System.out.println("SHIPPED.pay(): " + e.getMessage());
        }
    }
}

import java.util.Iterator;
import java.util.NoSuchElementException;

public class VisitorIteratorDemo {

    // ---- Visitor, modern style: a sealed hierarchy + pattern-matching switch ----
    sealed interface Expr permits Num, Add, Mul, Neg { }
    record Num(double value) implements Expr { }
    record Add(Expr left, Expr right) implements Expr { }
    record Mul(Expr left, Expr right) implements Expr { }
    record Neg(Expr operand) implements Expr { }

    // Each "visitor" is just a method. No accept(), no Visitor interface, exhaustive checking.
    static double eval(Expr e) {
        return switch (e) {
            case Num n -> n.value();
            case Add(Expr l, Expr r) -> eval(l) + eval(r);
            case Mul(Expr l, Expr r) -> eval(l) * eval(r);
            case Neg(Expr o) -> -eval(o);
        };
    }

    static String show(Expr e) {
        return switch (e) {
            case Num n -> String.valueOf(n.value());
            case Add(Expr l, Expr r) -> "(" + show(l) + " + " + show(r) + ")";
            case Mul(Expr l, Expr r) -> show(l) + " * " + show(r);
            case Neg(Expr o) -> "-" + show(o);
        };
    }

    // ---- Iterator: walk a structure without exposing it ----
    static class Countdown implements Iterable<Integer> {
        private final int from;
        Countdown(int from) { this.from = from; }

        @Override public Iterator<Integer> iterator() {
            return new Iterator<>() {
                private int next = from;
                @Override public boolean hasNext() { return next > 0; }
                @Override public Integer next() {
                    if (next <= 0) throw new NoSuchElementException();
                    return next--;
                }
            };
        }
    }

    public static void main(String[] args) {
        Expr e = new Add(new Num(2), new Mul(new Num(3), new Neg(new Num(4))));
        System.out.println(show(e) + " = " + eval(e));

        for (int i : new Countdown(3)) System.out.print(i + " ");
        System.out.println("liftoff");
    }
}

import java.util.*;

public class Effective {
    // Item: defensive copies. Broken version.
    static final class BrokenPeriod {
        private final Date start, end;
        BrokenPeriod(Date start, Date end) { this.start = start; this.end = end; }
        Date end() { return end; }
    }
    // Good version with java.time
    record Period(java.time.LocalDate start, java.time.LocalDate end) {
        Period {
            if (start.isAfter(end)) throw new IllegalArgumentException(start + " after " + end);
        }
    }

    // Immutable class with a mutable component
    static final class Roster {
        private final List<String> names;
        Roster(List<String> names) { this.names = List.copyOf(names); }
        List<String> names() { return names; }
    }
    static final class LeakyRoster {
        private final List<String> names;
        LeakyRoster(List<String> names) { this.names = names; }
        List<String> names() { return names; }
    }

    // Static factory with caching and a named constructor
    static final class Money {
        private static final Money ZERO = new Money(0);
        private final long cents;
        private Money(long cents) { this.cents = cents; }
        static Money ofCents(long c) { return c == 0 ? ZERO : new Money(c); }
        static Money ofDollars(double d) { return ofCents(Math.round(d * 100)); }
        @Override public String toString() {
            return "$" + cents / 100 + "." + String.format("%02d", cents % 100);
        }
    }

    // int constants vs enum
    static final int APPLE = 0, ORANGE = 1;
    enum Fruit { APPLE, ORANGE }

    // Optional as return type
    static Optional<String> findEmail(Map<String, String> db, String user) {
        return Optional.ofNullable(db.get(user));
    }

    // Composition vs inheritance: classic InstrumentedHashSet
    static class InstrumentedSet<E> extends HashSet<E> {
        int addCount;
        @Override public boolean add(E e) { addCount++; return super.add(e); }
        @Override public boolean addAll(Collection<? extends E> c) {
            addCount += c.size();
            return super.addAll(c);
        }
    }

    public static void main(String[] args) {
        Date start = new Date(0), end = new Date(86_400_000L);
        BrokenPeriod p = new BrokenPeriod(start, end);
        long before = p.end().getTime();
        end.setTime(0);              // attack from the outside
        System.out.println("end changed: " + (p.end().getTime() != before));
        p.end().setTime(-5);         // attack through the accessor
        System.out.println("end now: " + p.end().getTime());

        try {
            new Period(java.time.LocalDate.of(2026, 5, 2), java.time.LocalDate.of(2026, 5, 1));
        } catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }

        List<String> src = new ArrayList<>(List.of("Asha", "Ravi"));
        Roster safe = new Roster(src);
        LeakyRoster leaky = new LeakyRoster(src);
        src.add("Mallory");
        System.out.println(safe.names() + " vs " + leaky.names());
        try { safe.names().add("x"); }
        catch (UnsupportedOperationException e) { System.out.println("immutable view"); }

        System.out.println(Money.ofDollars(12.5) + " " + (Money.ofCents(0) == Money.ofDollars(0)));

        System.out.println((APPLE == ORANGE - 1) + " " + Fruit.APPLE
            + " " + Fruit.valueOf("ORANGE").ordinal());

        Map<String, String> db = Map.of("asha", "asha@example.com");
        System.out.println(findEmail(db, "asha").map(String::toUpperCase).orElse("none"));
        System.out.println(findEmail(db, "bob").orElse("none"));

        InstrumentedSet<String> s = new InstrumentedSet<>();
        s.addAll(List.of("a", "b", "c"));
        System.out.println("addCount = " + s.addCount);
    }
}

// Nested
double discount(Customer c) {
    if (c != null) {
        if (c.isActive()) {
            if (c.orders() > 10) {
                return 0.1;
            }
        }
    }
    return 0;
}

// Guard clauses: the same logic, flat
double discountFlat(Customer c) {
    if (c == null || !c.isActive()) return 0;
    if (c.orders() <= 10) return 0;
    return 0.1;
}

import java.util.*;

public class Refactor {
    // BEFORE: one method, mixed concerns, flag argument, magic numbers, deep nesting
    static double process(List<String[]> o, boolean vip, String type) {
        double t = 0;
        if (o != null) {
            for (String[] i : o) {
                if (i.length == 2) {
                    double p = Double.parseDouble(i[1]);
                    if (type.equals("food")) { t += p * 1.05; }
                    else { t += p * 1.2; }
                }
            }
            if (vip) { t = t * 0.9; }
        }
        return t;
    }

    // AFTER
    record Item(String name, double price) {}
    enum Category {
        FOOD(0.05), GENERAL(0.20);
        private final double taxRate;
        Category(double taxRate) { this.taxRate = taxRate; }
        double withTax(double price) { return price * (1 + taxRate); }
    }
    interface Discount { double apply(double total); }
    static final Discount NONE = total -> total;
    static final Discount VIP = total -> total * 0.9;

    static double total(List<Item> items, Category category, Discount discount) {
        double subtotal = items.stream().mapToDouble(i -> category.withTax(i.price())).sum();
        return discount.apply(subtotal);
    }

    // Dependency injection by hand
    interface Notifier { void send(String to, String msg); }
    interface UserRepo { Optional<String> emailOf(String user); }
    static class WelcomeService {
        private final UserRepo repo;
        private final Notifier notifier;
        WelcomeService(UserRepo repo, Notifier notifier) {
            this.repo = repo;
            this.notifier = notifier;
        }
        boolean welcome(String user) {
            return repo.emailOf(user)
                .map(email -> { notifier.send(email, "Welcome, " + user); return true; })
                .orElse(false);
        }
    }

    public static void main(String[] args) {
        List<String[]> old = List.of(new String[] {"rice", "100"}, new String[] {"dal", "50"});
        System.out.printf("before: %.2f%n", process(old, true, "food"));
        List<Item> items = List.of(new Item("rice", 100), new Item("dal", 50));
        System.out.printf("after:  %.2f%n", total(items, Category.FOOD, VIP));

        // production wiring
        UserRepo repo = u -> u.equals("asha") ? Optional.of("asha@example.com") : Optional.empty();
        Notifier console = (to, msg) -> System.out.println("MAIL to " + to + ": " + msg);
        System.out.println(new WelcomeService(repo, console).welcome("asha"));

        // test wiring: a fake notifier records what was sent
        List<String> sent = new ArrayList<>();
        WelcomeService svc = new WelcomeService(repo, (to, msg) -> sent.add(to + "|" + msg));
        System.out.println(svc.welcome("bob") + " " + sent);
        System.out.println(svc.welcome("asha") + " " + sent);
    }
}

// Safe: the ? placeholder is bound as a value, never parsed as SQL
String findName(Connection con, String user) throws SQLException {
    String sql = "SELECT display_name FROM users WHERE name = ?";
    try (PreparedStatement ps = con.prepareStatement(sql)) {
        ps.setString(1, user);
        try (ResultSet rs = ps.executeQuery()) {
            return rs.next() ? rs.getString(1) : null;
        }
    }
}

import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

public class Secure {
    // Path traversal: resolve, normalize, then check the result is still inside the base
    static Path resolveSafe(Path base, String userPath) {
        Path p = base.resolve(userPath).normalize();
        if (!p.startsWith(base)) throw new SecurityException("path escapes base: " + userPath);
        return p;
    }

    // Allow-list validation
    static void validateUsername(String s) {
        if (!s.matches("[A-Za-z0-9_]{3,16}")) throw new IllegalArgumentException("bad username");
    }

    // Secrets must not leak through toString
    record Token(String value) {
        @Override public String toString() { return "Token[****]"; }
    }

    static byte[] serialize(Object o) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(bos)) { oos.writeObject(o); }
        return bos.toByteArray();
    }

    static Object deserialize(byte[] data, ObjectInputFilter filter) throws Exception {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            ois.setObjectInputFilter(filter);
            return ois.readObject();
        }
    }

    public static void main(String[] args) throws Exception {
        Path base = Path.of("/srv/app/uploads").toAbsolutePath().normalize();
        System.out.println(resolveSafe(base, "report.pdf"));
        for (String evil : new String[] {"../../etc/passwd", "/etc/passwd"}) {
            try { System.out.println(resolveSafe(base, evil)); }
            catch (SecurityException e) { System.out.println(e.getMessage()); }
        }
        System.out.println("unchecked: " + base.resolve("../../etc/passwd").normalize());

        String user = "x' OR '1'='1";
        System.out.println("SELECT * FROM users WHERE name = '" + user + "'");

        for (String name : new String[] {"asha_01", "a; DROP"}) {
            try { validateUsername(name); System.out.println("ok " + name); }
            catch (IllegalArgumentException e) { System.out.println(e.getMessage() + ": " + name); }
        }

        byte[] raw = new byte[16];
        new SecureRandom().nextBytes(raw);
        System.out.println("token chars: " + HexFormat.of().formatHex(raw).length());

        byte[] a = "secret".getBytes(), b = "secret".getBytes();
        System.out.println("constant-time equal: " + MessageDigest.isEqual(a, b));
        System.out.println(new Token("abc123"));

        ObjectInputFilter allow = ObjectInputFilter.Config.createFilter(
            "java.lang.Integer;java.lang.Number;java.lang.Object;java.util.ArrayList;!*");
        System.out.println(deserialize(serialize(new ArrayList<>(List.of(1, 2))), allow));
        try {
            deserialize(serialize(new HashSet<>(List.of("x"))), allow);
        } catch (InvalidClassException e) {
            System.out.println("rejected: " + e.getMessage());
        }
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Supplier;
import java.util.stream.IntStream;

public class PerfDemo {
    static long sink;                       // consume results so the JIT cannot discard the work

    // Crude harness: warm up, then take the best of 5. NOT a substitute for JMH.
    static void time(String label, Supplier<Object> work) {
        for (int i = 0; i < 3; i++) sink += work.get().hashCode();
        long best = Long.MAX_VALUE;
        for (int i = 0; i < 5; i++) {
            long t0 = System.nanoTime();
            sink += work.get().hashCode();
            best = Math.min(best, System.nanoTime() - t0);
        }
        System.out.printf("%-34s %9.2f ms%n", label, best / 1e6);
    }

    public static void main(String[] args) {
        // 1. String building
        time("string += in a loop (20k)", () -> {
            String s = "";
            for (int i = 0; i < 20_000; i++) s += "x";
            return s;
        });
        time("StringBuilder (20k)", () -> {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 20_000; i++) sb.append("x");
            return sb.toString();
        });

        // 2. Boxing
        time("sum with Long (20M)", () -> {
            Long sum = 0L;
            for (int i = 0; i < 20_000_000; i++) sum += i;
            return sum;
        });
        time("sum with long (20M)", () -> {
            long sum = 0L;
            for (int i = 0; i < 20_000_000; i++) sum += i;
            return sum;
        });

        // 3. Collection sizing
        time("ArrayList default, 3M adds", () -> {
            List<Integer> l = new ArrayList<>();
            for (int i = 0; i < 3_000_000; i++) l.add(i);
            return l.size();
        });
        time("ArrayList presized, 3M adds", () -> {
            List<Integer> l = new ArrayList<>(3_000_000);
            for (int i = 0; i < 3_000_000; i++) l.add(i);
            return l.size();
        });

        // 4. Algorithm choice: 20k lookups in 100k elements
        List<Integer> list = new ArrayList<>();
        for (int i = 0; i < 100_000; i++) list.add(i * 2);
        Set<Integer> set = new HashSet<>(list);
        time("List.contains x 20k", () -> {
            int hits = 0;
            for (int i = 0; i < 20_000; i++) if (list.contains(i * 7)) hits++;
            return hits;
        });
        time("HashSet.contains x 20k", () -> {
            int hits = 0;
            for (int i = 0; i < 20_000; i++) if (set.contains(i * 7)) hits++;
            return hits;
        });

        // 5. Streams vs loops over primitives
        int[] data = IntStream.range(0, 10_000_000).toArray();
        time("loop: sum of squares (10M)", () -> {
            long s = 0;
            for (int v : data) s += (long) v * v;
            return s;
        });
        time("IntStream: sum of squares", () ->
            IntStream.of(data).mapToLong(v -> (long) v * v).sum());
        time("boxed Stream<Integer> version", () ->
            java.util.Arrays.stream(data).boxed().mapToLong(v -> (long) v * v).sum());
    }
}

import java.io.BufferedOutputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

public class PerfIoDemo {
    static final int BYTES = 300_000;
    static final Pattern ORDER_ID = Pattern.compile("\\w+-\\d+");     // compile once, reuse
    static final Map<Integer, Long> memo = new HashMap<>();

    static long fibSlow(int n) { return n < 2 ? n : fibSlow(n - 1) + fibSlow(n - 2); }
    static long fibMemo(int n) {
        if (n < 2) return n;
        Long cached = memo.get(n);
        if (cached != null) return cached;
        long v = fibMemo(n - 1) + fibMemo(n - 2);
        memo.put(n, v);
        return v;
    }

    static long timeMs(Runnable r) {
        long t0 = System.nanoTime();
        r.run();
        return (System.nanoTime() - t0) / 1_000_000;
    }

    static void write(Path p, boolean buffered) {
        try (OutputStream raw = new FileOutputStream(p.toFile());
             OutputStream out = buffered ? new BufferedOutputStream(raw) : raw) {
            for (int i = 0; i < BYTES; i++) out.write('x');
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public static void main(String[] args) throws IOException {
        Path file = Files.createTempFile("perf", ".bin");
        write(file, true);                                    // warm up
        System.out.println("unbuffered, " + BYTES + " write() calls: "
            + timeMs(() -> write(file, false)) + " ms");
        System.out.println("buffered,   " + BYTES + " write() calls: "
            + timeMs(() -> write(file, true)) + " ms");
        Files.delete(file);

        System.out.println("fib(35) recursive: " + timeMs(() -> fibSlow(35)) + " ms");
        System.out.println("fib(35) memoized:  " + timeMs(() -> fibMemo(35)) + " ms");

        long t = timeMs(() -> {
            int c = 0;
            for (int i = 0; i < 200_000; i++) if ("order-12345".matches("\\w+-\\d+")) c++;
        });
        long u = timeMs(() -> {
            int c = 0;
            for (int i = 0; i < 200_000; i++) if (ORDER_ID.matcher("order-12345").matches()) c++;
        });
        System.out.println("String.matches, 200k calls: " + t + " ms");
        System.out.println("precompiled Pattern, 200k:  " + u + " ms");
    }
}

